import csv,json,re,unicodedata
from collections import defaultdict
w=json.load(open('watchlist.json'))
byu={e['uid']:e for e in w}
cust={r['customer_id']:r for r in csv.DictReader(open('dev/customers_dev.csv'))}
labs=[l for l in csv.DictReader(open('dev/labels_dev.csv')) if l['expected_decision']=='MATCH']

def toks(n):
    n=n.replace(',',' ').replace('-',' ').replace("'"," ")
    return [t for t in n.split() if t]
PART={'al','el','bin','ibn','ben','bint','b','von','van','de','der','den','la','le','du','di','da','abu','the','of'}
def clean(n):
    return [t for t in toks(n) if t.lower().strip('.') not in PART and len(t.strip('.'))>1]

pairs=defaultdict(set)
un=[]
for l in labs:
    c=cust[l['customer_id']]; e=byu[l['expected_uid']]
    if e['type']!='individual': continue
    ct=clean(c['full_name'])
    names=[e['primary_name']]+[a['name'] for a in e['aliases'] if a['strength']=='strong']
    # pick best latin name
    best=None
    for n in names:
        if re.search(r'[a-zA-Z]',n):
            et=clean(n)
            if best is None or len(set(t.lower() for t in et)&set(t.lower() for t in ct))>len(best[1]&set(t.lower() for t in ct)):
                best=(et,set(t.lower() for t in et))
    if not best: 
        un.append((c['full_name'],e['primary_name'])); continue
    et=best[0]
    # align: family = last token both; given = first
    if len(ct)>=1 and len(et)>=1:
        pairs['fam'].add((ct[-1].lower(),et[-1].lower()))
        pairs['fam'].add((ct[0].lower(),et[-1].lower()))
        pairs['giv'].add((ct[0].lower(),et[0].lower()))
        pairs['giv'].add((ct[-1].lower(),et[0].lower()))
print('num unmatched-latin', len(un))
# Output fam pairs where tokens differ
def strip(s): return unicodedata.normalize('NFKD',s).encode('ascii','ignore').decode()
diff=sorted({(a,b) for a,b in pairs['fam'] if strip(a)!=strip(b)})
print(len(diff))
for a,b in diff: print(a,'->',b)
EOF

