#!/usr/bin/env python3
"""Score decisions against dev labels, overall and per class."""
import csv, sys, json
from collections import defaultdict

dec_path = sys.argv[1] if len(sys.argv) > 1 else '/app/dev/decisions_dev.csv'
lab_path = sys.argv[2] if len(sys.argv) > 2 else '/app/dev/labels_dev.csv'
cust_path = sys.argv[3] if len(sys.argv) > 3 else '/app/dev/customers_dev.csv'

dec = {r['customer_id']: r for r in csv.DictReader(open(dec_path))}
lab = {r['customer_id']: r for r in csv.DictReader(open(lab_path))}
cust = {r['customer_id']: r for r in csv.DictReader(open(cust_path))}

tp = fp = fn = 0
uid_ok = 0
percls = defaultdict(lambda: [0, 0])   # class -> [hit, total]
errors = defaultdict(list)
for cid, l in lab.items():
    d = dec.get(cid, {'decision': 'NO_MATCH', 'matched_uid': ''})
    exp = l['expected_decision']
    cls = l['class']
    got = d['decision']
    if exp == 'MATCH':
        percls[cls][1] += 1
        if got == 'MATCH':
            tp += 1
            percls[cls][0] += 1
            if d['matched_uid'] == l['expected_uid']:
                uid_ok += 1
            else:
                errors['WRONG_UID'].append((cid, cust[cid]['full_name'], d['matched_uid'], l['expected_uid'], cls))
        else:
            fn += 1
            errors['MISS'].append((cid, cust[cid]['full_name'], cust[cid]['dob'], l['expected_uid'], cls))
    else:
        percls[cls][1] += 1
        if got == 'MATCH':
            fp += 1
            errors['FP'].append((cid, cust[cid]['full_name'], cust[cid]['dob'], d['matched_uid'], cls))
        else:
            percls[cls][0] += 1

recall = tp / max(1, tp + fn)
prec = tp / max(1, tp + fp)
print('TP %d  FP %d  FN %d   recall %.4f  precision %.4f  uid_ok %.4f' %
      (tp, fp, fn, recall, prec, uid_ok / max(1, tp)))
print()
for cls in sorted(percls):
    hit, tot = percls[cls]
    kind = 'recall' if cls.startswith('T') else 'fp-rate'
    val = hit / tot if kind == 'recall' else (tot - hit) / tot
    flag = ''
    if kind == 'recall' and val < 0.90:
        flag = '  <-- LOW'
    if kind == 'fp-rate':
        lim = 0.01 if cls.startswith('R') else 0.05
        if val > lim:
            flag = '  <-- HIGH'
    print('%-28s %-8s %.3f  (%d/%d)%s' % (cls, kind, val, hit, tot, flag))

if len(sys.argv) > 4 or True:
    print()
    for k in ('MISS', 'FP', 'WRONG_UID'):
        v = errors[k]
        print('==== %s (%d)' % (k, len(v)))
        for row in v[:400]:
            print('   ', ' | '.join(str(x) for x in row))

