#!/usr/bin/env python3
import json, sys, csv
sys.path.insert(0, '/app')
import screen as S

entries = json.load(open('/app/watchlist.json'))
prep = S.prepare(entries)
S._build_nicknames()
idx, idx_id = S.build_index(prep)
byuid = {e.uid: e for e in prep}
raw = {e['uid']: e for e in entries}
cust = {r['customer_id']: r for r in csv.DictReader(open('/app/dev/customers_dev.csv'))}
lab = {r['customer_id']: r for r in csv.DictReader(open('/app/dev/labels_dev.csv'))}


def show(cid):
    c = cust[cid]
    l = lab[cid]
    print('customer', c)
    print('label', l)
    cf = S.person_forms(c['full_name'])
    print('cforms', cf)
    uid = l['expected_uid']
    if uid:
        e = raw[uid]
        print('entry', json.dumps(e, ensure_ascii=False))
        ent = byuid[uid]
        print('eforms', ent.strong, ent.org, ent.vessel)
