        toks = set()
        for g, f in cf:
            toks |= set(g) | set(f)
        cand = S.candidates(idx, toks)
        print('in candidates:', any(prep[i].uid == uid for i in cand), 'ncand', len(cand))
    print('decision', S.screen_customer(c, prep, idx, idx_id))


def why(a, b):
    print(repr(a), S.token_keys(a))
    print(repr(b), S.token_keys(b))
    print('match', S.tokens_match(a, b), 'given', S.given_match(a, b))


if __name__ == '__main__':
    for cid in sys.argv[1:]:
        if cid.startswith('D') and cid in cust:
            show(cid)
            print('-' * 60)

