def token_keys(tok):
    """-> (strict plain, strict weak, loose plain, loose weak, is_arabic)"""
    hit = _key_cache.get(tok)
    if hit is not None:
        return hit
    sc = script_of(tok)
    if sc == 'ar':
        base = tok
        if base.startswith('ال') and len(base) > 3:
            base = base[2:]
        loose = _arabic_keys(base)
