#!/usr/bin/env python3
"""Stress the engine with romanisation conventions absent from the dev set."""
import json, re, sys, random, csv
sys.path.insert(0, '/app')
import screen as S

W = json.load(open('/app/watchlist.json'))
prep = S.prepare(W)
S._build_nicknames()
idx, idx_id = S.build_index(prep)
raw = {e['uid']: e for e in W}


def decide(name, dob='', typ='individual'):
    row = {'customer_id': 'X', 'full_name': name, 'dob': dob,
           'nationality': '', 'id_type': '', 'id_number': '', 'type': typ}
    return S.screen_customer(row, prep, idx, idx_id)


# ---------------------------------------------------------------- conventions
def _w(fn):
    def apply(name):
        return ' '.join(fn(t) for t in name.split())
    return apply


def turkish(t):
    low = t.lower()
    p = low
    p = p.replace('kh', 'h').replace('gh', 'g')
    p = p.replace('sh', 'ş').replace('ch', 'ç')
    p = p.replace('j', 'c')
    p = p.replace('q', 'k')
    p = p.replace('ou', 'u').replace('oo', 'u').replace('ee', 'i')
    p = p.replace('ai', 'ay').replace('ei', 'ey')
    p = re.sub(r'd$', 't', p)
    p = re.sub(r'^hu', 'hü', p)
    p = re.sub(r'ss', 's', p)
    return p.capitalize()


def indonesian(t):
    low = t.lower()
    p = low
    p = p.replace('kh', 'ch')
    p = p.replace('sh', 'sj')
    p = p.replace('ch', 'tj') if not p.startswith('ch') else p
    p = p.replace('j', 'dj')
    p = re.sub(r'^y', 'j', p)
    p = p.replace('u', 'oe').replace('oo', 'oe')
    p = p.replace('ou', 'oe')
    return p.capitalize()


def malay(t):
    low = t.lower()
    p = low.replace('sh', 'sy').replace('kh', 'kh').replace('u', 'u')
    p = re.sub(r'^y', 'j', p)
    return p.capitalize()


def polish(t):
    low = t.lower()
    p = low
    p = p.replace('shch', 'szcz')
    p = p.replace('sh', 'sz').replace('ch', 'cz').replace('zh', 'ż')
    p = p.replace('v', 'w')
    p = p.replace('kh', 'ch')
    p = p.replace('ts', 'c')
    return p.capitalize()


def scientific(t):
    low = t.lower()
    p = low
    p = p.replace('shch', 'sc')
    p = p.replace('sh', 's').replace('ch', 'c').replace('zh', 'z')
    p = p.replace('ts', 'c')
    p = p.replace('kh', 'h')
    p = re.sub(r'y', 'j', p)
    p = re.sub(r'ij$', 'ij', p)
    p = re.sub(r'([^aeiou])j$', r'\1ij', p)
    return p.capitalize()


def scientific2(t):
    """-y endings written -ij, ai->aj"""
    p = scientific(t)
    p = p.replace('ai', 'aj').replace('ei', 'ej')
    return p


def gulf(t):
    low = t.lower()
    p = low
    p = p.replace('ou', 'u')
    p = p.replace('kh', 'kh')
    p = re.sub(r'^mohammed$', 'mohamed', p)
    p = p.replace('q', 'g') if p.startswith('q') else p
    p = p.replace('th', 'th')
    p = re.sub(r'ee', 'i', p)
    return p.capitalize()


def german(t):
    low = t.lower()
    p = low.replace('sh', 'sch').replace('ch', 'tsch').replace('zh', 'sch')
    p = p.replace('v', 'w')
    p = re.sub(r'w$', 'ff', p)
    p = re.sub(r'^y', 'j', p)
    p = p.replace('ya', 'ja').replace('yu', 'ju')
    p = p.replace('ts', 'z')
    return p.capitalize()


def french(t):
    low = t.lower()
    p = low.replace('sh', 'ch').replace('ch', 'tch').replace('zh', 'j')
    p = p.replace('u', 'ou')
    p = re.sub(r'v$', 'ff', p)
    p = p.replace('y', 'i')
    return p.capitalize()


def sunletter(name):
    """al-Rashid -> ar-Rashid"""
    def rep(m):
        art, rest = m.group(1), m.group(2)
        c = rest[:2].lower() if rest[:2].lower() in ('sh', 'th', 'dh') else rest[0].lower()
        if c in ('t', 'th', 'd', 'dh', 'r', 'z', 's', 'sh', 'n', 'l'):
            return 'a' + c + '-' + rest
        return art + rest
    return re.sub(r'\b([Aa]l-|[Ee]l-)([A-Za-z]+)', rep, name)


def attach_article(name):
    return re.sub(r'\b([Aa]l-|[Ee]l-)([A-Za-z]+)', lambda m: m.group(1)[:-1] + m.group(2), name)


def drop_article(name):
    return re.sub(r'\b[Aa]l-|\b[Ee]l-', '', name)


def reorder(name):
    t = name.split()
    if len(t) < 2:
        return name
    return t[-1] + ', ' + ' '.join(t[:-1])


def reorder2(name):
    t = name.split()
    if len(t) < 2:
        return name
    return t[-1] + ' ' + ' '.join(t[:-1])


def drop_nasab(name):
    return re.sub(r'\s+(bin|ibn|ben|bint)\s+\S+', '', name)


def epenthetic(name):
    t = name.split()
    return ' '.join(x + 'e' if not x.endswith(('e', 'a', 'i', 'o', 'u')) and len(x) > 3 and '-' not in x else x for x in t)


CONVS = {
    'turkish': _w(turkish), 'indonesian': _w(indonesian), 'malay': _w(malay),
    'polish': _w(polish), 'scientific': _w(scientific),
    'scientific2': _w(scientific2), 'gulf': _w(gulf), 'german': _w(german),
    'french': _w(french),
    'sunletter': sunletter, 'attach_article': attach_article,
    'drop_article': drop_article, 'reorder': reorder, 'reorder2': reorder2,
    'drop_nasab': drop_nasab, 'epenthetic': epenthetic,
}

STACK = [
    ('turkish+reorder', lambda n: reorder(_w(turkish)(n))),
    ('indonesian+drop_nasab', lambda n: _w(indonesian)(drop_nasab(n))),
    ('polish+reorder2', lambda n: reorder2(_w(polish)(n))),
    ('scientific+reorder', lambda n: reorder(_w(scientific)(n))),
    ('gulf+sunletter', lambda n: _w(gulf)(sunletter(n))),
    ('turkish+attach', lambda n: attach_article(_w(turkish)(n))),
    ('scientific2+epenthetic', lambda n: _w(scientific2)(n)),
    ('german+drop_nasab', lambda n: _w(german)(drop_nasab(n))),
]


def latin_name(e):
    n = e['primary_name']
    if re.search(r'[A-Za-z]', n):
        return n
    for a in e['aliases']:
        if a['strength'] == 'strong' and re.search(r'[A-Za-z]', a['name']):
            return a['name']
    return None


def run(kind='individual', limit=None, verbose=0):
    ents = [e for e in W if e['type'] == kind]
    if limit:
        ents = ents[:limit]
    fails = {}
    tot = {}
    examples = {}
    for e in ents:
        base = latin_name(e)
        if not base:
            continue
        convs = list(CONVS.items()) + STACK
        for cname, fn in convs:
            try:
                nm = fn(base)
            except Exception:
                continue
            if nm == base and cname not in ('base',):
                pass
            dec, uid = decide(nm, e['dob'], kind)
            tot[cname] = tot.get(cname, 0) + 1
            if uid != e['uid']:
                fails[cname] = fails.get(cname, 0) + 1
                examples.setdefault(cname, []).append((base, nm, e['uid'], uid))
    for c in sorted(tot):
        f = fails.get(c, 0)
        print('%-24s %5d/%5d  fail %.3f' % (c, f, tot[c], f / tot[c]))
        if verbose:
            for ex in examples.get(c, [])[:verbose]:
                print('        %-38s -> %-38s  want %s got %s' % ex)


if __name__ == '__main__':
    v = int(sys.argv[2]) if len(sys.argv) > 2 else 0
    run(sys.argv[1] if len(sys.argv) > 1 else 'individual', verbose=v)

