#!/usr/bin/env python3
"""Adversarial precision test.

Build look-alike customers the way the sample's decoy classes do -- keep the
family name, swap the given name for one that belongs to a different name,
then re-spell the result in each romanisation convention.  By construction no
watchlist entry carries that combination, so every MATCH is a false positive.
"""
import json, re, sys, random
sys.path.insert(0, '/app')
import screen as S
import stress as ST

W = ST.W
random.seed(11)


def latin_pairs():
    out = []
    for e in W:
        if e['type'] != 'individual':
            continue
        nm = ST.latin_name(e)
        if not nm:
            continue
        forms, _ = S.person_forms(nm, canonical=True)
        if not forms:
            continue
        giv, fam = forms[0]
        if len(giv) != 1 or len(fam) != 1:
            continue
        out.append((e, giv[0], fam[0]))
    return out


pairs = latin_pairs()
print('entries with a simple latin name:', len(pairs))

# cluster given names / family names with the engine itself
def cluster(words, matcher):
    reps = []
    cid = {}
    for w in sorted(words):
        for i, r in enumerate(reps):
            if matcher(w, r):
                cid[w] = i
                break
        else:
            cid[w] = len(reps)
            reps.append(w)
    return cid


givens = {g for _, g, _ in pairs}
families = {f for _, _, f in pairs}
gc = cluster(givens, S.given_match)
fc = cluster(families, S.tokens_match)
print('given clusters %d/%d  family clusters %d/%d' %
      (len(set(gc.values())), len(givens), len(set(fc.values())), len(families)))

# which (given cluster, family cluster) combinations exist
combos = set()
for e, g, f in pairs:
    combos.add((gc[g], fc[f]))

glist = sorted(givens)
convs = list(ST.CONVS.items()) + ST.STACK
fp = 0
tot = 0
examples = []
for e, g, f in pairs:
    for _ in range(3):
        cand = random.choice(glist)
        if (gc[cand], fc[f]) not in combos and gc[cand] != gc[g]:
            break
    else:
        continue
    name = cand + ' ' + f
    cname, fn = random.choice(convs)
    try:
